import XCTest
@testable import ColorComposerCore

// MARK: - Corpus wire model
//
// Mirrors `priv/parity/v1/corpus.json` published by viamin/color_matching
// (generated by `ColorMatching.Parity.Corpus`, PR viamin/color_matching#112 —
// the parity-corpus dependency this suite consumes). See docs/parity-corpus.md
// for the refresh procedure.

private struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let scorer: String
    let selection: String
    let missingPolicy: String
    let lightSources: [String]
    let scenarios: [ParityScenario]

    enum CodingKeys: String, CodingKey {
        case algorithmVersion = "algorithm_version"
        case scorer
        case selection
        case missingPolicy = "missing_policy"
        case lightSources = "light_sources"
        case scenarios
    }
}

private struct ParityScenario: Decodable {
    let id: String
    let description: String
    let weights: [String: Double]
    let target: ParityVector
    let palette: [ParityVector]
    let expected: ParityExpected
}

private struct ParityVector: Decodable {
    let index: Int?
    let hexColor: String
    let channels: [String: Double]

    enum CodingKeys: String, CodingKey {
        case index
        case hexColor = "hex_color"
        case channels
    }
}

private struct ParityExpected: Decodable {
    let scores: [ParityScoreEntry]
    let selectedIndex: Int?
    let selectedHexColor: String?
    let error: Double?
    let tieBroke: Bool?
    let tiedIndices: [Int]

    enum CodingKeys: String, CodingKey {
        case scores
        case selectedIndex = "selected_index"
        case selectedHexColor = "selected_hex_color"
        case error
        case tieBroke = "tie_broke"
        case tiedIndices = "tied_indices"
    }
}

private struct ParityScoreEntry: Decodable {
    let index: Int
    let score: ParityScore
}

/// A per-candidate expectation: a finite float, or the string `"excluded"`.
private enum ParityScore: Decodable, Equatable {
    case excluded
    case value(Double)

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let excluded = try? container.decode(String.self), excluded == "excluded" {
            self = .excluded
        } else {
            self = .value(try container.decode(Double.self))
        }
    }

    var isExcluded: Bool { self == .excluded }

    var scoreValue: Double? {
        guard case .value(let v) = self else { return nil }
        return v
    }
}

private enum ParityFixtureError: Error {
    case malformed
}

// MARK: - Corpus-backed solver parity

/// Replays the committed solver-parity corpus against
/// `WeightedSquaredErrorScorer` and `CompositionSolver` and asserts the
/// selections match the Elixir reference implementation exactly — including
/// tie cases (earliest-index-wins), missing-measurement exclusions, and
/// channel weighting.
final class SolverParityCorpusTests: XCTestCase {
    private static var fixtureHint: String {
        "parity corpus fixture missing at " + Self.fixtureURL.path
            + " — copy priv/parity/v1/corpus.json from viamin/color_matching (see docs/parity-corpus.md)"
    }

    private static var fixtureURL: URL {
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/parity/v1/corpus.json")
    }

    private func loadCorpus(file: StaticString = #filePath, line: UInt = #line) throws -> ParityCorpus {
        guard FileManager.default.fileExists(atPath: Self.fixtureURL.path) else {
            XCTFail(Self.fixtureHint, file: file, line: line)
            throw ParityFixtureError.malformed
        }
        do {
            return try JSONDecoder().decode(ParityCorpus.self, from: Data(contentsOf: Self.fixtureURL))
        } catch {
            XCTFail("parity corpus fixture is not decodable: \(error)", file: file, line: line)
            throw ParityFixtureError.malformed
        }
    }

    private func makeWeights(_ raw: [String: Double]) -> ChannelWeights {
        func weight(_ condition: LightingCondition) -> Double {
            raw[condition.rawValue] ?? 0
        }
        return ChannelWeights(
            white: weight(.white),
            red: weight(.red),
            green: weight(.green),
            blue: weight(.blue),
            lps: weight(.lps)
        )
    }

    private func makeResponses(_ channels: [String: Double]) -> [LightingCondition: IlluminationResponse] {
        var responses: [LightingCondition: IlluminationResponse] = [:]
        for (key, value) in channels {
            guard let condition = LightingCondition(rawValue: key) else { continue }
            responses[condition] = IlluminationResponse(brightness: value)
        }
        return responses
    }

    private func makePalette(_ vectors: [ParityVector], scenarioID: String,
                             file: StaticString = #filePath, line: UInt = #line) throws -> [PaletteColor] {
        try vectors.enumerated().map { position, vector in
            guard vector.index == position else {
                XCTFail("scenario \(scenarioID): palette index \(String(describing: vector.index)) != position \(position)",
                        file: file, line: line)
                throw ParityFixtureError.malformed
            }
            guard let rgb = RGBColor(hex: vector.hexColor) else {
                XCTFail("scenario \(scenarioID): unparseable hex \(vector.hexColor)", file: file, line: line)
                throw ParityFixtureError.malformed
            }
            return PaletteColor(
                id: position,
                hex: vector.hexColor,
                rgb: rgb,
                responses: makeResponses(vector.channels)
            )
        }
    }

    private func makeTarget(_ vector: ParityVector) -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in vector.channels {
            guard let condition = LightingCondition(rawValue: key) else { continue }
            brightness[condition] = value
        }
        return TargetResponseVector(brightness)
    }

    /// Scenario ids must be unique so failures name exactly one scenario.
    func testScenarioIDsAreUnique() throws {
        let corpus = try loadCorpus()
        let ids = corpus.scenarios.map(\.id)
        XCTAssertEqual(ids.count, Set(ids).count, "duplicate scenario ids in corpus")
    }

    /// The corpus records which scorer/selection semantics it was generated
    /// from; any change here means every expectation may have moved and the
    /// mirrored Swift implementation must be re-audited.
    func testCorpusMetadataMatchesImplementedSolverSemantics() throws {
        let corpus = try loadCorpus()

        XCTAssertEqual(corpus.algorithmVersion, 1, "corpus algorithm_version moved; re-audit scorer parity")
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, LightingCondition.all.map(\.rawValue))
        XCTAssertFalse(corpus.scenarios.isEmpty)
    }

    /// A corpus swap that silently drops tie, exclusion, or unknown-weight
    /// coverage would hollow out this suite; require that coverage to exist.
    func testCorpusCoversTiesExclusionsNoSelectionAndUnknownWeights() throws {
        let corpus = try loadCorpus()

        XCTAssertTrue(corpus.scenarios.contains { $0.expected.tieBroke == true }, "no tie scenario")
        XCTAssertTrue(
            corpus.scenarios.contains { $0.expected.scores.contains { $0.score.isExcluded } },
            "no exclusion scenario"
        )
        XCTAssertTrue(corpus.scenarios.contains { $0.expected.selectedIndex == nil }, "no no-selection scenario")
        XCTAssertTrue(
            corpus.scenarios.contains { $0.target.channels.count < LightingCondition.all.count },
            "no partially-measured target scenario"
        )
        XCTAssertTrue(
            corpus.scenarios.contains { scenario in
                scenario.weights.keys.contains { LightingCondition(rawValue: $0) == nil }
            },
            "no unknown-light-source weight scenario"
        )
    }

    /// Every per-candidate score in the corpus must reproduce exactly — the
    /// same IEEE 754 doubles as the Elixir scorer, not merely close — and
    /// `:excluded` must map to `.excluded` (missing never treated as zero).
    func testScorerScoresMatchCorpusExactly() throws {
        let corpus = try loadCorpus()
        let scorer = WeightedSquaredErrorScorer()

        for scenario in corpus.scenarios {
            let weights = makeWeights(scenario.weights)
            let target = makeTarget(scenario.target)
            let palette = try makePalette(scenario.palette, scenarioID: scenario.id)

            XCTAssertEqual(palette.count, scenario.expected.scores.count, "scenario \(scenario.id)")

            for (candidate, expected) in zip(palette, scenario.expected.scores) {
                let result = scorer.score(candidate: candidate, target: target, weights: weights)
                switch (result, expected.score) {
                case (.excluded, .excluded):
                    continue
                case let (.score(actual), .value(expectedValue)):
                    XCTAssertEqual(actual, expectedValue, "scenario \(scenario.id) candidate \(candidate.id)")
                case (.excluded, .value(let expectedValue)):
                    XCTFail("scenario \(scenario.id) candidate \(candidate.id): expected score \(expectedValue), got .excluded")
                case (.score(let actual), .excluded):
                    XCTFail("scenario \(scenario.id) candidate \(candidate.id): expected .excluded, got score \(actual)")
                }
            }
        }
    }

    /// The solver's per-cell selection must be the corpus's selection: the
    /// earliest palette index among the tied minima, or no match at all when
    /// every candidate is excluded. A target missing a positively-weighted
    /// channel cannot be built from source grids, so that exclusion shape is
    /// asserted at scorer level (see testScorerScoresMatchCorpusExactly).
    func testSolverSelectionsMatchCorpusExactlyIncludingTies() throws {
        let corpus = try loadCorpus()

        for scenario in corpus.scenarios {
            let weights = makeWeights(scenario.weights)
            let active = weights.activeEntries.map(\.condition)
            let targetMeasuresEveryActiveChannel = active.allSatisfy { condition in
                scenario.target.channels[condition.rawValue] != nil
            }

            if !targetMeasuresEveryActiveChannel {
                XCTAssertNil(scenario.expected.selectedIndex, "scenario \(scenario.id)")
                XCTAssertTrue(scenario.expected.scores.allSatisfy { $0.score.isExcluded }, "scenario \(scenario.id)")
                continue
            }

            let palette = try makePalette(scenario.palette, scenarioID: scenario.id)
            let grids: [LightingCondition: BrightnessGrid] = Dictionary(
                uniqueKeysWithValues: active.map { condition in
                    (condition, BrightnessGrid(width: 1, height: 1, fill: scenario.target.channels[condition.rawValue]!))
                }
            )

            let result = try CompositionSolver(scorer: WeightedSquaredErrorScorer())
                .solve(palette: palette, sourceGrids: grids, weights: weights)

            let selectedIndex = result.colorIndex(x: 0, y: 0)
            XCTAssertEqual(selectedIndex, scenario.expected.selectedIndex, "scenario \(scenario.id)")
            XCTAssertEqual(
                selectedIndex.map { palette[$0].hex },
                scenario.expected.selectedHexColor,
                "scenario \(scenario.id)"
            )

            if let expectedError = scenario.expected.error {
                XCTAssertEqual(result.error(x: 0, y: 0), expectedError, "scenario \(scenario.id)")
            } else {
                XCTAssertTrue(result.error(x: 0, y: 0).isInfinite, "scenario \(scenario.id)")
                XCTAssertEqual(result.unmatchedCellCount, 1, "scenario \(scenario.id)")
            }
        }
    }

    /// Tie evidence must be self-consistent: `tied_indices` lists every
    /// candidate at the minimum score, the selection is the earliest of them,
    /// and `tie_broke` is true exactly when more than one is tied.
    func testTieEvidenceIsConsistentAndEarliestIndexWins() throws {
        let corpus = try loadCorpus()

        for scenario in corpus.scenarios {
            let expected = scenario.expected
            let ranked = expected.scores.compactMap { entry in
                entry.score.scoreValue.map { (entry.index, $0) }
            }
            guard !ranked.isEmpty else {
                XCTAssertNil(expected.selectedIndex, "scenario \(scenario.id)")
                XCTAssertTrue(expected.tiedIndices.isEmpty, "scenario \(scenario.id)")
                XCTAssertNil(expected.tieBroke, "scenario \(scenario.id)")
                continue
            }

            let minimum = ranked.map { $0.1 }.min()!
            let tied = ranked.filter { $0.1 == minimum }.map { $0.0 }

            XCTAssertEqual(tied, expected.tiedIndices, "scenario \(scenario.id)")
            XCTAssertEqual(tied.first, expected.selectedIndex, "scenario \(scenario.id)")
            XCTAssertEqual(expected.tieBroke, tied.count > 1, "scenario \(scenario.id)")
        }
    }

    /// Corpus weights arrive as a light-source map that may carry unknown
    /// sources (e.g. `ultraviolet`); only the five canonical conditions may
    /// influence scoring, and unknown keys must not exclude anyone. The
    /// corpus's expected scores for such a scenario were computed by an
    /// Elixir scorer that filters unknown weights, so the exact-score test
    /// above already proves the numeric parity; this pins the mapping.
    func testUnknownWeightKeysAreIgnoredNotTreatedAsRequired() throws {
        let corpus = try loadCorpus()
        let scenario = try XCTUnwrap(
            corpus.scenarios.first { scenario in
                scenario.weights.keys.contains { LightingCondition(rawValue: $0) == nil }
            }
        )

        let weights = makeWeights(scenario.weights)
        let canonical: Set<String> = Set(LightingCondition.all.map(\.rawValue))
        let unknownKeys = scenario.weights.keys.filter { !canonical.contains($0) }

        XCTAssertFalse(unknownKeys.isEmpty, "scenario \(scenario.id) must carry an unknown weight key")
        for condition in LightingCondition.all {
            XCTAssertEqual(
                weights.weight(for: condition),
                scenario.weights[condition.rawValue] ?? 0,
                "scenario \(scenario.id)"
            )
        }
        XCTAssertEqual(
            weights.activeEntries.map(\.condition),
            LightingCondition.all.filter { (scenario.weights[$0.rawValue] ?? 0) > 0 },
            "scenario \(scenario.id): unknown keys must not activate or deactivate canonical channels"
        )
        XCTAssertNotNil(
            scenario.expected.selectedIndex,
            "scenario \(scenario.id): an unknown weight key must not exclude every candidate"
        )
    }
}
